Core 提供 [[IF-core-directory|轻量引用目录合同]]，并在此保留已核实消费者。Maintenance 的 annotation-records 接入读取有限摘录、引用状态、定位和可见修订；订阅持久变化，只有明确 tombstone 才同步删除。该镜像只读，不接管 Core 发送、撤销或完整上下文。

镜像接入说明、所属逻辑会话映射和恢复实现的入口由 Maintenance 独立项目的 INT-annotation 维护，项目 ID 为 0d05f813-7097-47d9-9e88-3d523bb537d6。按该项目与条目 ID 定位；Core 目录的唯一合同仍在本图。该关系不证明目标实例已启用；本次没有运行镜像服务。

提供方变更应检查此消费者支持的分页、修订和删除范围。返回 [[MOD-core|Core 已知接入目录]]及[[IF-core-directory|唯一目录合同]]。此页沿用 INT-maintenance-directory 身份，原外部目录位置已归并。

import { useEffect, useState } from 'react';
import { bridgeSettingsStyles } from './binding-settings-style.ts';
import type { ObsidianBridgeLifecycle, VaultConnectionSnapshot } from './api.ts';

export interface BridgeSettingsSlots {
  inject(name: string, register: () => (() => void)): () => void;
  register(options: Record<string, unknown>, component: typeof BridgeSettings): () => void;
}

/** Only the current host's unbound/owned channels are editable here. */
export async function changeCurrentBinding(lifecycle: ObsidianBridgeLifecycle, vault: VaultConnectionSnapshot, operationId: string): Promise<void> {
  const identity = lifecycle.getInstanceIdentity?.();
  if (!identity || !lifecycle.changeVaultBinding) throw new Error('当前实例连接服务尚未就绪');
  if (vault.state !== 'bound' && vault.state !== 'available') throw new Error('请在 Vault 中断开原连接，再刷新此面板');
  const owned = vault.binding.target?.instanceId === identity.instanceId && vault.binding.target.profileId === identity.profileId;
  if (vault.state === 'bound' ? !owned : vault.binding.target !== null) throw new Error('Vault 连接状态已改变，请刷新');
  await lifecycle.changeVaultBinding(vault.vaultId, {
    operationId, expectedRevision: vault.binding.revision,
    intent: owned ? 'unbind' : 'bind',
    target: owned ? null : { instanceId: identity.instanceId, profileId: identity.profileId },
    ...(!owned ? { candidate: { origin: identity.origin, bootId: identity.bootId } } : {}),
  });
}

const connectionLabels: Record<string, string> = {
  READY: '已连接', STARTING: '正在连接', DEGRADED: '连接受限', OFFLINE: '等待连接',
  DRAINING: '正在断开', STOPPED: '已停止', FAILED: '连接失败',
};

export function BridgeSettings({ lifecycle }: { lifecycle: ObsidianBridgeLifecycle }) {
  const [vaults, setVaults] = useState(() => lifecycle.listVaults?.() ?? []);
  const [busy, setBusy] = useState<string>();
  const [feedback, setFeedback] = useState('');
  useEffect(() => lifecycle.subscribe(() => setVaults(lifecycle.listVaults?.() ?? [])), [lifecycle]);
  const run = async (key: string, action: () => Promise<void>) => {
    if (busy) return;
    setBusy(key); setFeedback('');
    try { await action(); setVaults(lifecycle.listVaults?.() ?? []); }
    catch (error) { setFeedback(error instanceof Error ? error.message : '连接操作失败，请刷新后检查状态'); }
    finally { setBusy(undefined); }
  };
  const labels = { bound: '已绑定此实例', available: '可连接', foreign: '已连接其他实例', offline: '离线', conflict: '身份冲突' };
  const cliAvailable = lifecycle.getCliAvailability?.().available ?? false;
  return <section className="dsh-bridge-settings" aria-label="Obsidian 连接设置" aria-busy={Boolean(busy)}>
    <style>{bridgeSettingsStyles}</style>
    <header className="dsh-bridge-settings__heading">
      <h3>Obsidian 连接</h3>
      <p>连接你的笔记仓库，在 DSH 与 Obsidian 之间打开笔记和会话。</p>
    </header>
    <div className="dsh-bridge-settings__toolbar">
      <h4>笔记仓库 <span className="dsh-bridge-settings__count">{vaults.length}</span></h4>
      <button type="button" className="dsh-bridge-settings__button" disabled={Boolean(busy)} onClick={() => { void run('refresh', async () => { await lifecycle.refreshVaults?.(); }); }}>{busy === 'refresh' ? '正在刷新…' : '刷新列表'}</button>
    </div>
    {vaults.length === 0 ? <div className="dsh-bridge-settings__empty"><strong>尚未发现笔记仓库</strong><p>请在 Obsidian 中打开 Vault 并启用 Companion，然后刷新列表。无需启动 Maintenance。</p></div> : <ul className="dsh-bridge-settings__list">{vaults.map(vault => {
      const label = vault.state === 'bound' ? connectionLabels[vault.connectionState ?? ''] ?? labels.bound : labels[vault.state];
      return <li key={vault.vaultId} className="dsh-bridge-settings__vault">
        <div className="dsh-bridge-settings__row">
          <div className="dsh-bridge-settings__identity"><strong>{vault.displayName}</strong><span className="dsh-bridge-settings__badge" data-connected={vault.state === 'bound' && vault.connectionState === 'READY'}>{label}</span></div>
          {vault.state === 'available' || vault.state === 'bound' ? <button type="button" className="dsh-bridge-settings__button" disabled={Boolean(busy)} onClick={() => { void run(vault.vaultId, () => changeCurrentBinding(lifecycle, vault, crypto.randomUUID())); }}>{busy === vault.vaultId ? '正在处理…' : vault.state === 'bound' ? '断开连接' : '连接此仓库'}</button> : null}
        </div>
        {vault.state === 'foreign' ? <p className="dsh-bridge-settings__hint">如需连接此实例，请先在该仓库的 Companion 设置中断开原连接。</p> : null}
        {vault.state === 'offline' ? <p className="dsh-bridge-settings__hint">打开此仓库并启用 Companion 后，可重新检查连接。</p> : null}
        {vault.state === 'conflict' ? <p className="dsh-bridge-settings__hint">请核对仓库身份后再连接。</p> : null}
        <details className="dsh-bridge-settings__details"><summary>连接详情</summary><dl><dt>仓库标识</dt><dd>{vault.vaultId}</dd>{vault.origin ? <><dt>连接地址</dt><dd>{vault.origin}</dd></> : null}</dl></details>
      </li>;
    })}</ul>}
    <p className="dsh-bridge-settings__note">一个 DSH 实例可连接多个仓库，每个仓库同时连接一个实例。断开连接会保留笔记、引用和双链。</p>
    <div className="dsh-bridge-settings__cli"><div><strong>Obsidian CLI</strong><p>可选增强，不影响基础桥接。</p></div><span className="dsh-bridge-settings__badge" data-connected={cliAvailable}>{cliAvailable ? '可用' : '未配置'}</span></div>
    {feedback ? <output className="dsh-bridge-settings__feedback" role="alert">{feedback}</output> : null}
  </section>;
}

export function registerBridgeSettings(slots: BridgeSettingsSlots, lifecycle: ObsidianBridgeLifecycle): () => void {
  return slots.inject('settings.section', () => slots.register({
    name: 'settings.section', id: 'obsidian-bridge', label: 'Obsidian 连接', order: 85,
    inject: () => ({ lifecycle }),
  }, BridgeSettings));
}

import {assertMaintenanceSessionAvailable} from "../session-availability.ts";
import { resolveMaintenanceLocation, type ReferenceLocation } from "./bridge/maintenance-location.ts";
import type { Context as CordisContext } from "@deepseek-ai/cordis";
import type { AnnotationCoreClient } from "dsh-annotation-core/client-api";
import type { ObsidianBridgeLifecycle } from "../api.ts";

import { BridgeHttpError, bridgeSurfaceIdFromUrl } from "./bridge/http-client.ts";
import { createReferenceDeleteActionHandler } from "./bridge/reference-delete-actions.ts";
import type { OpenNoteAction } from "./protocol.ts";
import { consumeObsidianReferenceCapture } from "./client/annotation-consumer.ts";


type SessionOpeningCore = AnnotationCoreClient & {
  openAnnotationInSession?: (sessionId: string, setId: string, referenceId?: string) => Promise<boolean>;
};
type Context = CordisContext & {
  annotationCore: SessionOpeningCore;
  obsidianBridgeLifecycle: ObsidianBridgeLifecycle;
  sessions: {
    list: { getSnapshot(): { current?: string }; subscribe?(listener: () => void): () => void };
    open(sessionId: string): void;
  };
};



function openSourceAction(notePath: string, blockId?: string): OpenNoteAction {
  return {
    protocolVersion: 1,
    type: "open-note",
    actionId: crypto.randomUUID(),
    notePath,
    ...(blockId === undefined ? {} : { blockId }),
  };
}

export function apply(ctx: Context): void {
  const surfaceId = typeof location === "undefined" ? undefined : bridgeSurfaceIdFromUrl(location.href);
  const identity = ctx.obsidianBridgeLifecycle.runtimeIdentity;
  const profileId = identity?.profileId ?? "web";
  const instance = identity?.dshInstanceId;
  const instanceScope = instance === undefined ? {} : { dshInstanceId: instance };
  const bridge = ctx.obsidianBridgeLifecycle.transport!;
  const resolveLocation = (location: ReferenceLocation) => {
    if (ctx.obsidianBridgeLifecycle.hasReferenceLocationResolver?.() === false) {
      if (location.logicalSessionId) throw new Error("此历史引用需要会话解析服务，当前实例未提供该能力");
      return Promise.resolve(undefined);
    }
    return resolveMaintenanceLocation(location);
  };
  const deletionHandler = (transport:typeof bridge)=>createReferenceDeleteActionHandler(ctx.annotationCore, transport, profileId, {
    ...instanceScope,
    resolveSession: async action => {
      if (action.type !== "reference-delete-request") return undefined;
      const resolved = await resolveLocation(action);
      await assertMaintenanceSessionAvailable(resolved?.logicalSessionId??action.logicalSessionId);
      return resolved?.sessionId ?? (action.logicalSessionId ? undefined : action.sessionId);
    },
  });
  const unregisterSource = ctx.annotationCore.registerSourceAdapter("obsidian-note", {
    async openSource(item) {
      if (item.sourceType !== "obsidian-note") throw new TypeError("Expected an Obsidian reference");
      await (ctx.obsidianBridgeLifecycle.forVault?.(item.locator.vaultId)??bridge).openNote(openSourceAction(item.locator.notePath, item.locator.blockId));
    },
  });
  const unregisterAttachment = ctx.obsidianBridgeLifecycle.registerActionHandler!("references:client", {
      accepts: action => action.type === "reference-capture" || (action.type === "reference-delete-request" && action.profileId === profileId) || (action.type === "deep-link" && action.setId !== undefined),
      handle: async (action, signal, route) => {
        const actionBridge=route?.transport??bridge;
        signal.throwIfAborted();
        if (action.type === "reference-delete-request") {
          return await deletionHandler(actionBridge)(action) ? "handled" : "retry";
        }
        if (action.type === "reference-capture") {
          // The companion also checks its persisted Web Viewer identity. Do
          // not mutate Core from a standalone page, including with old servers.
          if (surfaceId === undefined) return "ignored";
          if(route&&action.source.locator.vaultId!==route.vaultId)throw new Error("Reference capture Vault identity mismatch");
          const sessionId = ctx.sessions.list.getSnapshot().current;
          if (!sessionId) return "retry";
          if (action.dshInstanceId !== undefined && action.dshInstanceId !== instance) return "ignored";
          const target = await resolveLocation({ sessionId });
          await assertMaintenanceSessionAvailable(target?.logicalSessionId);
          if (target !== undefined && target.sessionId !== sessionId) throw new Error("Capture resolver changed the receiving session identity");
          try { await consumeObsidianReferenceCapture({
            signal,
            capture: action,
            sessionId,
            profileId,
            logicalTarget: { ...instanceScope, legacySessionId: sessionId,
              ...(target?.logicalSessionId ? { logicalSessionId: target.logicalSessionId } : {}) },
            annotationCore: ctx.annotationCore,
            bridge:actionBridge,
          }); } catch (error) {
            if (error instanceof BridgeHttpError && (error.code === "idempotency-conflict" || error.status === 404 || error.status === 410)) return "cancelled";
            throw error;
          }
          return "handled";
        }
        if (action.type === "deep-link" && action.setId !== undefined) {
          if (action.targetSurfaceId !== undefined && action.targetSurfaceId !== surfaceId) return "ignored";
          if (action.dshInstanceId !== undefined && action.dshInstanceId !== instance) return "ignored";
          const resolved = await resolveLocation(action);
          await assertMaintenanceSessionAvailable(resolved?.logicalSessionId??action.logicalSessionId);
          if (action.logicalSessionId && resolved === undefined) return "retry";
          const targetSessionId = resolved?.sessionId ?? action.sessionId;
          await ctx.sessions.open(targetSessionId);
          if (typeof ctx.annotationCore.openAnnotationInSession === "function") {
            return await ctx.annotationCore.openAnnotationInSession(targetSessionId, action.setId, action.referenceId) ? "handled" : "retry";
          }
          ctx.annotationCore.openAnnotation(action.setId, action.referenceId);
          return "handled";
        }
        return "ignored";
      },
  });
      let previousSession = ctx.sessions.list.getSnapshot().current;
      const unsubscribe = ctx.sessions.list.subscribe?.(() => {
        const current = ctx.sessions.list.getSnapshot().current;
        if (current && current !== previousSession) ctx.obsidianBridgeLifecycle.retryActions?.();
        previousSession = current;
      });
      const visibility = () => { if (document.visibilityState !== "hidden") ctx.obsidianBridgeLifecycle.retryActions?.(); };
      if (typeof document !== "undefined") document.addEventListener("visibilitychange", visibility);
  ctx.effect(() => async () => {
    unregisterAttachment();
    unregisterSource();
    unsubscribe?.();
    if (typeof document !== "undefined") document.removeEventListener("visibilitychange", visibility);
  }, "dsh-obsidian-bridge: references: client");
}

