/** Forward only the explicit target; the authenticated runtime must not rewrite legacy identities. */
function stickerBacklinkTarget(sticker: StickerRecord): Record<string, string> {
  const target: Record<string, string> = {
    stickerId: sticker.stickerId,
    sessionId: sticker.sessionId,
    anchorId: sticker.anchorId,
    quoteHash: sticker.quoteHash,
  };
  if (sticker.vaultId !== undefined) target.vaultId = sticker.vaultId;
  for (const key of Object.keys(stableLogicalTargetShape) as (keyof typeof stableLogicalTargetShape)[]) {
    const value = sticker[key];
    if (value !== undefined) target[key] = value;
  }
  return target;
}

export function normalizeBridgeOrigin(value: string): string {
  const url = new URL(value);
  if (url.protocol !== "http:" || (url.hostname !== "127.0.0.1" && url.hostname !== "localhost")) {
    throw new TypeError(`Obsidian bridge must use an HTTP loopback origin: ${value}`);
  }
  if (url.pathname !== "/" || url.search || url.hash || url.username || url.password) {
    throw new TypeError("Obsidian bridge origin cannot contain a path, query or fragment");
  }
  return url.origin;
}

export const DSH_BRIDGE_SURFACE_PARAMETER = "dshBridgeSurface";
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function bridgeSurfaceIdFromUrl(value: string): string | undefined {
  const url = new URL(value);
  const fragment = new URLSearchParams(url.hash.replace(/^#/, ""));
  const surfaceId = (
    fragment.get(DSH_BRIDGE_SURFACE_PARAMETER)
    ?? url.searchParams.get(DSH_BRIDGE_SURFACE_PARAMETER)
    ?? undefined
  )?.trim();
  return surfaceId !== undefined && UUID_PATTERN.test(surfaceId) ? surfaceId : undefined;
}

async function responseError(response: Response): Promise<BridgeHttpError> {
  let message = `Bridge returned HTTP ${response.status}`;
  let code: BridgeErrorCode = "http-error";
  try {
    const body = await response.json() as { error?: unknown; code?: unknown };
    if (typeof body.error === "string") message = body.error;
    if (typeof body.code === "string") code = ERROR_CODES[body.code] ?? "http-error";
  } catch {
    // Keep the bounded fallback above.
  }
  return new BridgeHttpError(response.status, code, message);
}

export function createBridgeHttpClient(options: BridgeHttpClientOptions): BridgeHttpClient {
  const origin = normalizeBridgeOrigin(options.origin);
  const fetchImplementation = options.fetch ?? globalThis.fetch.bind(globalThis);
  const now = options.now ?? Date.now;
  const clientId = options.clientId ?? `dsh-sticker-${crypto.randomUUID()}`;
  const surfaceId = options.surfaceId?.trim();
  if (surfaceId !== undefined && !UUID_PATTERN.test(surfaceId)) {
    throw new TypeError("DSH bridge surface ID must be a UUID");
  }
  const requiredCapabilities = [
    "reference-capture-v2",
    "reference-refresh",
    "backlink-commit-v2",
    "reference-delete-v2",
    "sticker-backlink-delete-v1",
    ...(options.vaultId === undefined ? [] : ["vault-instance-binding-v1"]),
    ...(surfaceId === undefined ? [] : ["targeted-deep-link-v1"]),
    ...(options.dshInstanceId === undefined ? [] : ["instance-routing-v1"]),
  ];
  const requests = createRequestScope(fetchImplementation, options.requestTimeoutMs);
  let token: string | null = null;
  let tokenExpiresAt = 0;
  let disposed = false;

  async function request(path: string, init: RequestInit = {}): Promise<Response> {
    if (disposed) throw new DOMException("Bridge client disposed", "AbortError");
    const headers = new Headers(init.headers);
    if (options.requestOrigin) headers.set("origin", options.requestOrigin);
    try {
      return await requests.request(`${origin}${path}`, { ...init, headers });
    } catch (error) {
      if (error instanceof DOMException) throw error;
      throw new BridgeUnavailableError(`Obsidian bridge is unavailable at ${origin}`, { cause: error });
    }
  }

  async function handshake(force = false, signal?: AbortSignal): Promise<void> {
    if (!force && token !== null && tokenExpiresAt > now() + 1_000) return;
    const response = await request("/v2/handshake", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ clientId, ...(options.dshInstanceId === undefined ? {} : { dshInstanceId: options.dshInstanceId }), ...(surfaceId === undefined ? {} : { surfaceId }), ...(options.vaultId === undefined ? {} : {bindingProtocolVersion:1,vaultId:options.vaultId,bindingRevision:options.bindingRevision,profileId:options.profileId,dshBootId:options.dshBootId}) }),
      ...(signal === undefined ? {} : { signal }),
    });
    if (!response.ok) throw await responseError(response);
    const body = await response.json() as {
      token?: unknown;
      expiresAt?: unknown;
      annotationProtocolVersion?: unknown;
      stickerProtocolVersion?: unknown;
      bridgeOrigin?: unknown;
      surfaceId?: unknown;
      dshInstanceId?: unknown;
      capabilities?: unknown;
      vaultId?: unknown; bindingRevision?: unknown; profileId?: unknown; dshBootId?: unknown;
    };
    const capabilities = Array.isArray(body.capabilities) ? body.capabilities : [];
    if (
      typeof body.token !== "string" || typeof body.expiresAt !== "number"
      || body.annotationProtocolVersion !== ANNOTATION_PROTOCOL_VERSION
      || body.stickerProtocolVersion !== STICKER_PROTOCOL_VERSION
      || body.bridgeOrigin !== origin
      || (options.dshInstanceId !== undefined && body.dshInstanceId !== options.dshInstanceId)
      || (options.vaultId !== undefined && (body.vaultId !== options.vaultId || body.bindingRevision !== options.bindingRevision || body.profileId !== options.profileId || body.dshBootId !== options.dshBootId))
      || (surfaceId !== undefined && body.surfaceId !== surfaceId)
      || !requiredCapabilities.every((item) => capabilities.includes(item))
    ) {
      throw new BridgeHttpError(409, "protocol-mismatch", "Obsidian bridge does not provide the required protocol v2 capabilities");
    }
    token = body.token;
    tokenExpiresAt = body.expiresAt;
  }

  async function authenticated(path: string, init: RequestInit = {}, canRetry = true): Promise<Response> {
    await handshake(false, init.signal ?? undefined);
    init.signal?.throwIfAborted();
    const headers = new Headers(init.headers);
    headers.set("authorization", `Bearer ${token}`);
    const response = await request(path, { ...init, headers });
    if (response.status === 401 && canRetry) {
      token = null;
      tokenExpiresAt = 0;
      await handshake(true, init.signal ?? undefined);
      return authenticated(path, init, false);
    }
    if (!response.ok) throw await responseError(response);
    return response;
  }

  async function post(path: string, value: unknown, signal?: AbortSignal): Promise<Response> {
    return authenticated(path, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(value),
      ...(signal === undefined ? {} : { signal }),
    });
  }

  async function acknowledgeOneShot(actionId: string, signal?: AbortSignal): Promise<void> {
    try {
      await post(`/v1/actions/${encodeURIComponent(actionId)}/ack`, {}, signal);
    } catch (error) {
      // Another live DSH surface may have consumed the same one-shot action
      // after this client fetched it. Historical Bridge versions return 404
      // for that harmless race, which must not turn into an infinite retry.
      if (error instanceof BridgeHttpError && error.status === 404) return;
      throw error;
    }
  }

  return {
    origin,
    async knowledge(operation, input) {
      if (!/^[a-z-]{1,40}$/.test(operation)) throw new TypeError('Invalid knowledge operation');
      const response = await post('/v1/knowledge/' + operation, input);
      return response.json();
    },
    async preflight() {
      const response = await request("/v2/health");
      if (!response.ok) throw await responseError(response);
      const body = await response.json() as {
        annotationProtocolVersion?: unknown;
        stickerProtocolVersion?: unknown;
        bridgeOrigin?: unknown;
        capabilities?: unknown;
      };
      const capabilities = Array.isArray(body.capabilities) ? body.capabilities : [];
      if (
        body.annotationProtocolVersion !== ANNOTATION_PROTOCOL_VERSION
        || body.stickerProtocolVersion !== STICKER_PROTOCOL_VERSION
        || body.bridgeOrigin !== origin
        || !requiredCapabilities.every((item) => capabilities.includes(item))
      ) {
        throw new BridgeHttpError(409, "protocol-mismatch", "Host, Client and Obsidian bridge configuration do not agree");
      }
      await handshake();
    },
    async nextActions(after, signal) {
      if (!Number.isInteger(after) || after < 0) throw new TypeError("Bridge cursor must be a non-negative integer");
      const response = await authenticated(`/v2/actions/pending?after=${after}`, signal === undefined ? {} : { signal });
      const body = await response.json() as { queueId?: unknown; cursor?: unknown; actions?: unknown };
      if (!Number.isInteger(body.cursor) || !Array.isArray(body.actions)) throw new Error("Bridge action page is invalid");
      if (body.queueId !== undefined && (typeof body.queueId !== "string" || body.queueId === "")) {
        throw new Error("Bridge queue ID is invalid");
      }
      const actions = body.actions.map((value): QueuedBridgeAction => {
        if (typeof value !== "object" || value === null) throw new Error("Bridge queue entry is invalid");
        const entry = value as { cursor?: unknown; message?: unknown };
        if (!Number.isInteger(entry.cursor) || (entry.cursor as number) < 0) throw new Error("Bridge action cursor is invalid");
        const capture = ObsidianReferenceCaptureV2Schema.safeParse(entry.message);
        const deletion = ReferenceDeleteRequestV2Schema.safeParse(entry.message);
        const message = capture.success ? capture.data : deletion.success ? deletion.data : deepLinkActionSchema.parse(entry.message);
        return { cursor: entry.cursor as number, message };
      });
      return {
        ...(typeof body.queueId === "string" ? { queueId: body.queueId } : {}),
        cursor: body.cursor as number,
        actions,
      };
    },
    async acknowledgeDeepLink(actionId, signal) {
      await acknowledgeOneShot(actionId, signal);
    },
    async acknowledgeAction(actionId, signal) {
      await acknowledgeOneShot(actionId, signal);
    },
    async claimReference(actionId, claim, signal) {
      await post(`/v2/actions/${encodeURIComponent(actionId)}/ack`, claim, signal);
    },
    async refreshReference(referenceId, knownDocumentHash, signal) {
      const response = await post(`/v2/references/${encodeURIComponent(referenceId)}/refresh`, {
        annotationProtocolVersion: ANNOTATION_PROTOCOL_VERSION,
        type: "reference-refresh",
        referenceId,
        knownDocumentHash,
      }, signal);
      return ReferenceRefreshResultV2Schema.parse(await response.json());
    },
    async discardReference(referenceId) {
      await post(`/v2/references/${encodeURIComponent(referenceId)}/discard`, {
        annotationProtocolVersion: ANNOTATION_PROTOCOL_VERSION,
        type: "reference-discard",
        referenceId,
      });
    },
    async commitBacklink(commit) {
      const response = await post("/v2/backlinks/commit", commit);
      return BacklinkReceiptV2Schema.parse(await response.json());
    },
    async deleteCommittedReference(commit) {
      await post(`/v2/references/${encodeURIComponent(commit.referenceId)}/delete-commit`, commit);
    },
    async readSessionNote(sessionId) {
      const response = await authenticated(`/v1/session-notes/${encodeURIComponent(sessionId)}`);
      const message = parseBridgeMessage(await response.json());
      if (message.type !== "session-note") throw new Error("Bridge did not return a session note");
      if (options.vaultId && message.vaultId && message.vaultId !== options.vaultId) throw new Error("Session note Vault mismatch");
      return options.vaultId ? {...message,vaultId:options.vaultId} : message;
    },
    async saveSessionNote(document, expectedRevision) {
      if (options.vaultId && document.vaultId && document.vaultId !== options.vaultId) throw new Error("Session note Vault mismatch");
      const response = await authenticated(`/v1/session-notes/${encodeURIComponent(document.sessionId)}`, {
        method: "PUT",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ document, expectedRevision }),
      });
      const body = await response.json() as { revision?: unknown };
      if (typeof body.revision !== "string") throw new Error("Bridge save response has no revision");
      return { revision: body.revision };
    },
    async openNote(action) {
      if (options.vaultId && action.vaultId && action.vaultId !== options.vaultId) throw new Error("Open note Vault mismatch");
      await post("/v2/obsidian/open-note", action);
    },
    async listBacklinks(sticker) {
      const query = new URLSearchParams(stickerBacklinkTarget(sticker));
      const response = await authenticated(`/v1/sticker-backlinks?${query.toString()}`);
      const body = await response.json() as { backlinks?: unknown };
      return stickerBacklinkSchema.array().parse(body.backlinks);
    },
    async deleteStickerBacklinks(sticker) {
      if (options.vaultId && sticker.vaultId && sticker.vaultId !== options.vaultId) throw new Error("Sticker backlink Vault mismatch");
      const response = await post("/v1/sticker-backlinks/delete", stickerBacklinkTarget(sticker));
      return stickerBacklinkDeleteResultSchema.parse(await response.json());
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      requests.abort();
    },
  };
}

import { BridgeActionChannel } from "./action-channel.ts";
import {
  BRIDGE_LIFECYCLE_PROTOCOL_VERSION,
  acceptsBridgeWork,
  type BridgeIdentity,
  type BridgeStatus,
  type ObservedBridgeStatus,
} from "dsh-obsidian-bridge-protocol";

import type { BridgeHealthSource, BridgeLifecycleHealth, BridgeAttachmentDisposer, BridgeAttachmentMount, ObsidianBridgeLifecycle, ReadyBridgeStatus } from "./api.ts";
import { createBridgeControlClient, type BridgeControlClient } from "./control-client.ts";

interface Attachment {
  name: string;
  mount: BridgeAttachmentMount;
  disposer: BridgeAttachmentDisposer | undefined;
  bootId?: string;
}

export interface LifecycleRuntimeOptions {
  bridgeOrigin: string;
  clientId: string;
  role: "controller" | "surface";
  dshInstanceId?: string;
  browserOrigins?: readonly string[];
  dshViewerUrl?: string;
  requestOrigin?: string;
  surfaceId?: string;
  profileId?: string;
  vaultId?: string;
  bindingRevision?: number;
  dshBootId?: string;
  dshOrigin?: string;
  pollIntervalMs?: number;
  requestTimeoutMs?: number;
  leaseTtlMs?: number;
  fetch?: typeof globalThis.fetch;
  now?: () => number;
  setTimer?: (callback: () => void, delay: number) => ReturnType<typeof setTimeout>;
  clearTimer?: (timer: ReturnType<typeof setTimeout>) => void;
  onError?: (error: unknown) => void;
}

export class BridgeLifecycleRuntime implements ObsidianBridgeLifecycle {
  readonly bridgeOrigin: string;
  readonly capabilities = Object.freeze(["reference-channel-v1", "action-dispatch-v1"]);
  private readonly channel: BridgeActionChannel;
  get transport() { return this.channel.borrowedTransport; }
  registerActionHandler: NonNullable<ObsidianBridgeLifecycle["registerActionHandler"]> = (name, handler) => this.channel.registerActionHandler(name, handler);
  retryActions = () => this.channel.retryActions();
  private readonly control: BridgeControlClient;
  private readonly attachments: Attachment[] = [];
  private readonly healthSources = new Map<string, BridgeHealthSource>();
  private readonly healthSubscriptions = new Map<string, () => void>();
  private readonly listeners = new Set<() => void>();
  private readonly pollIntervalMs: number;
  private readonly leaseTtlMs: number;
  private readonly browserOrigins: readonly string[];
  private readonly dshViewerUrl: string | undefined;
  private readonly now: () => number;
  private readonly setTimer: NonNullable<LifecycleRuntimeOptions["setTimer"]>;
  private readonly clearTimer: NonNullable<LifecycleRuntimeOptions["clearTimer"]>;
  private readonly onError: (error: unknown) => void;
  private timer?: ReturnType<typeof setTimeout>;
  private stopped = false;
  private started = false;
  private generation = 0;
  private inFlight?: Promise<void>;
  private shutdown?: Promise<void>;
  private leaseExpiresAt = 0;
  private transition: Promise<void> = Promise.resolve();
  private lastKnownIdentity?: BridgeIdentity;
  private snapshot: ObservedBridgeStatus;

  constructor(options: LifecycleRuntimeOptions) {
    this.control = createBridgeControlClient({
      origin: options.bridgeOrigin,
      clientId: options.clientId,
      role: options.role,
      ...(options.vaultId === undefined ? {} : {vaultId:options.vaultId,bindingRevision:options.bindingRevision!,profileId:options.profileId!,dshBootId:options.dshBootId!,dshOrigin:options.dshOrigin!}),
      ...(options.dshInstanceId === undefined ? {} : { dshInstanceId: options.dshInstanceId }),
      ...(options.requestTimeoutMs === undefined ? {} : { requestTimeoutMs: options.requestTimeoutMs }),
      ...(options.fetch === undefined ? {} : { fetch: options.fetch }),
      ...(options.requestOrigin === undefined ? {} : { requestOrigin: options.requestOrigin }),
    });
    this.bridgeOrigin = this.control.origin;
    this.pollIntervalMs = options.pollIntervalMs ?? 1_000;
    this.leaseTtlMs = options.leaseTtlMs ?? 15_000;
    this.browserOrigins = Object.freeze([...(options.browserOrigins ?? [])]);
    this.dshViewerUrl = options.dshViewerUrl;
    this.now = options.now ?? Date.now;
    this.setTimer = options.setTimer ?? globalThis.setTimeout.bind(globalThis);
    this.clearTimer = options.clearTimer ?? globalThis.clearTimeout.bind(globalThis);
    this.onError = options.onError ?? (() => undefined);
    this.snapshot = {
      lifecycleProtocolVersion: BRIDGE_LIFECYCLE_PROTOCOL_VERSION,
      state: "OFFLINE",
      stateChangedAt: this.now(),
      reason: "Bridge status has not been observed yet",
    };
    this.channel = new BridgeActionChannel(this, {
      ...(options.vaultId === undefined ? {} : {vaultId:options.vaultId,bindingRevision:options.bindingRevision!,dshBootId:options.dshBootId!}),
      origin: this.bridgeOrigin, clientId: `${options.clientId}:actions`, role: options.role,
      ...(options.profileId === undefined ? {} : { profileId: options.profileId }),
      ...(options.dshInstanceId === undefined ? {} : { dshInstanceId: options.dshInstanceId }),
      ...(options.surfaceId === undefined ? {} : { surfaceId: options.surfaceId }),
      ...(options.requestOrigin === undefined ? {} : { requestOrigin: options.requestOrigin }),
      ...(options.fetch === undefined ? {} : { fetch: options.fetch }),
      ...(options.requestTimeoutMs === undefined ? {} : { requestTimeoutMs: options.requestTimeoutMs }),
    });
  }

  getSnapshot(): ObservedBridgeStatus { return this.snapshot; }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  }

  start(): void {
    if (this.started || this.stopped) return;
    this.started = true;
    this.inFlight = this.poll();
  }

  getHealth(): BridgeLifecycleHealth {
    return { state: this.snapshot.state, bridgeOrigin: this.bridgeOrigin,
      components: Object.fromEntries([...this.healthSources].map(([name, source]) => [name, source.getHealth()])) };
  }

  registerHealthSource(name: string, source: BridgeHealthSource): () => void {
    if (this.stopped) return () => undefined;
    this.healthSubscriptions.get(name)?.();
    this.healthSources.set(name, source);
    const unsubscribe = source.subscribe?.(() => { for (const listener of [...this.listeners]) listener(); });
    if (unsubscribe !== undefined) this.healthSubscriptions.set(name, unsubscribe);
    return () => {
      if (this.healthSources.get(name) !== source) return;
      unsubscribe?.(); this.healthSources.delete(name); this.healthSubscriptions.delete(name);
    };
  }

  retry(name?: string): void {
    if (this.stopped) return;
    if (name !== undefined) { if (!this.stopped) this.healthSources.get(name)?.retry?.(); return; }
    for (const source of this.healthSources.values()) source.retry?.();
    if (this.stopped) return;
    if (this.timer !== undefined) this.clearTimer(this.timer);
    this.inFlight = (this.inFlight ?? Promise.resolve()).then(() => {
      if (this.timer !== undefined) this.clearTimer(this.timer);
      return this.poll();
    });
  }

  mountWhenReady(name: string, mount: BridgeAttachmentMount): () => void {
    if (this.stopped) return () => undefined;
    if (this.attachments.some((attachment) => attachment.name === name)) {
      throw new Error(`Bridge attachment ${JSON.stringify(name)} is already registered`);
    }
    const attachment: Attachment = { name, mount, disposer: undefined };
    this.attachments.push(attachment);
    this.queueReconcile();
    return () => {
      const index = this.attachments.indexOf(attachment);
      if (index >= 0) this.attachments.splice(index, 1);
      this.transition = this.transition.then(async () => {
        const disposer = attachment.disposer;
        attachment.disposer = undefined;
        await disposer?.();
      }).catch(this.onError);
    };
  }

  async drain(reason: string, deadlineMs = 10_000): Promise<void> {
    if (this.stopped) return;
    const generation = this.generation;
    const status = await this.control.drain(reason, deadlineMs);
    if (!this.stopped && generation === this.generation) await this.observe(status);
  }

  async resume(): Promise<void> {
    if (this.stopped) return;
    const generation = this.generation;
    const status = await this.control.resume();
    if (!this.stopped && generation === this.generation) await this.observe(status);
  }

  dispose(): Promise<void> {
    if (this.shutdown !== undefined) return this.shutdown;
    this.stopped = true;
    this.generation += 1;
    if (this.timer !== undefined) this.clearTimer(this.timer);
    this.control.cancelPending();
    this.snapshot = {
      lifecycleProtocolVersion: BRIDGE_LIFECYCLE_PROTOCOL_VERSION, state: "OFFLINE",
      stateChangedAt: this.now(), reason: "Bridge lifecycle stopped",
    };
    this.shutdown = (async () => {
      await Promise.resolve();
      for (const listener of [...this.listeners]) listener();
      await this.inFlight;
      await this.unmountAll();
      await this.channel.dispose();
      this.control.dispose();
      this.listeners.clear();
      for (const unsubscribe of this.healthSubscriptions.values()) unsubscribe();
      this.healthSubscriptions.clear();
      this.healthSources.clear();
    })();
    return this.shutdown;
  }

  private async poll(): Promise<void> {
    if (this.stopped) return;
    const generation = this.generation;
    try {
      const status = await this.control.status();
      if (this.stopped || generation !== this.generation) return;
      if (this.lastKnownIdentity?.bootId !== status.bootId) this.leaseExpiresAt = 0;
      this.lastKnownIdentity = {
        lifecycleProtocolVersion: status.lifecycleProtocolVersion,
        instanceId: status.instanceId,
        bootId: status.bootId,
        bridgeVersion: status.bridgeVersion,
        startedAt: status.startedAt,
      };
      if (this.leaseExpiresAt <= this.now() + this.leaseTtlMs / 2) {
        const lease = this.leaseExpiresAt === 0
          ? await this.control.acquireLease(this.leaseTtlMs, this.browserOrigins, this.dshViewerUrl)
          : await this.control.renewLease(this.leaseTtlMs, this.browserOrigins, this.dshViewerUrl);
        if (this.stopped || generation !== this.generation) return;
        if (lease.bootId !== status.bootId) throw new Error("Bridge lease belongs to another boot");
        this.leaseExpiresAt = lease.expiresAt;
      }
      await this.observe(status);
    } catch (error) {
      if (this.stopped || generation !== this.generation) return;
      this.leaseExpiresAt = 0;
      const reason = error instanceof Error ? error.message : String(error);
      const alreadyReported = this.snapshot.state === "OFFLINE" && this.snapshot.reason === reason;
      if (!alreadyReported) this.onError(error);
      await this.observe({
        lifecycleProtocolVersion: BRIDGE_LIFECYCLE_PROTOCOL_VERSION,
        state: "OFFLINE",
        stateChangedAt: alreadyReported ? this.snapshot.stateChangedAt : this.now(),
        ...(this.lastKnownIdentity === undefined ? {} : { lastKnownIdentity: this.lastKnownIdentity }),
        reason,
      });
    } finally {
      if (!this.stopped) this.timer = this.setTimer(() => { this.inFlight = this.poll(); }, this.pollIntervalMs);
    }
  }

  private async observe(status: ObservedBridgeStatus): Promise<void> {
    if (this.stopped) return;
    const changed = JSON.stringify(status) !== JSON.stringify(this.snapshot);
    this.snapshot = status;
    if (changed) for (const listener of [...this.listeners]) listener();
    this.queueReconcile();
    await this.transition;
  }

  private queueReconcile(): void {
    this.transition = this.transition.then(async () => {
      if (this.stopped || !acceptsBridgeWork(this.snapshot)) {
        await this.unmountAllNow();
        return;
      }
      const ready = this.snapshot as ReadyBridgeStatus;
      if (this.attachments.some((item) => item.disposer !== undefined && item.bootId !== ready.bootId)) await this.unmountAllNow();
      const generation = this.generation;
      for (const attachment of [...this.attachments]) {
        if (this.stopped || generation !== this.generation) break;
        if (!this.attachments.includes(attachment) || attachment.disposer !== undefined) continue;
        const disposer = await attachment.mount(ready);
        if (this.stopped || generation !== this.generation || !this.attachments.includes(attachment)
          || !acceptsBridgeWork(this.snapshot) || this.snapshot.bootId !== ready.bootId) {
          await disposer?.();
          continue;
        }
        attachment.bootId = ready.bootId;
        attachment.disposer = disposer ?? (() => undefined);
      }
    }).catch((error) => { this.onError(error); });
  }

  private async unmountAll(): Promise<void> {
    await this.transition;
    await this.unmountAllNow();
  }

  private async unmountAllNow(): Promise<void> {
    for (const attachment of [...this.attachments].reverse()) {
      const disposer = attachment.disposer;
      attachment.disposer = undefined;
      try { await disposer?.(); } catch (error) { this.onError(error); }
    }
  }
}

