# Companion 接入共享控制、数据及 Annotation 2

Companion 是 Obsidian 插件，Bridge server 直接导入 [Protocol 控制合同：身份、租约与状态](../../../../../../../dsh-obsidian-bridge/docs/project/records/modules/bridge-protocol/interfaces/control.md) 校验控制请求并管理实际租约、状态和服务；它是协议消费者与 HTTP 服务提供者，不是 Protocol 的子产品。

本地 protocol.ts 从 [Protocol 数据合同：贴纸、定位与导航](../../../../../../../dsh-obsidian-bridge/docs/project/records/modules/bridge-protocol/interfaces/data.md) 导出数据消息，使用 stableLogicalTargetShape 扩展 claim/删除目标；Annotation 2 的 capture、快照、claim、refresh、回链和删除基础模型来自 [Core Annotation 2 合同：引用捕获与生命周期消息](../../../../../../../dsh-annotation-core/docs/project/records/modules/annotation-core/interfaces/annotation-protocol.md)。扩展严格校验保留目标边界，但不会为旧记录发明逻辑身份。

实际笔记队列与回链服务见 [[IF-companion-reference]]，直接关联引用见 [[IF-companion-knowledge]]；协议定义不保存 Vault 正文、Owned 标记或同步回执，这些属于 [[MOD-companion-vault]]。

源码入口：[server.ts](../../../../../../../../worktrees/rc2-adapt-20260912/obsidian-deepharness-bridge/src/bridge/server.ts)、[protocol.ts](../../../../../../../../worktrees/rc2-adapt-20260912/obsidian-deepharness-bridge/src/protocol.ts)。

返回 [共享协议接入目录](../../../../../../../dsh-obsidian-bridge/docs/project/records/modules/bridge-protocol/overview.md)；Annotation 2 返回 [Core Annotation 2 合同：引用捕获与生命周期消息](../../../../../../../dsh-annotation-core/docs/project/records/modules/annotation-core/interfaces/annotation-protocol.md)。

import { z } from "zod";
import { bindingControlFields } from './binding.ts';
export * from './binding.ts';

export const BRIDGE_LIFECYCLE_PROTOCOL_VERSION = 3 as const;

export const bridgeBrowserOriginSchema = z.string().url().superRefine((value, context) => {
  const url = new URL(value);
  if (url.protocol !== "http:" || (url.hostname !== "127.0.0.1" && url.hostname !== "localhost")) {
    context.addIssue({ code: "custom", message: "Browser origin must use loopback HTTP" });
  }
  if (url.origin !== value || url.username !== "" || url.password !== "") {
    context.addIssue({ code: "custom", message: "Browser origin must not contain credentials, a path, query or fragment" });
  }
});
export type BridgeBrowserOrigin = z.infer<typeof bridgeBrowserOriginSchema>;

export const bridgeBrowserOriginsSchema = z.array(bridgeBrowserOriginSchema).max(8);

export const bridgeDshViewerUrlSchema = z.string().url().superRefine((value, context) => {
  const url = new URL(value);
  if (url.protocol !== "http:" || (url.hostname !== "127.0.0.1" && url.hostname !== "localhost")) {
    context.addIssue({ code: "custom", message: "DSH Viewer URL must use loopback HTTP" });
  }
  if (url.username !== "" || url.password !== "" || url.pathname !== "/" || url.hash !== "") {
    context.addIssue({ code: "custom", message: "DSH Viewer URL must be a credential-free loopback root URL without a fragment" });
  }
  const keys = [...url.searchParams.keys()];
  if (keys.some((key) => key !== "token") || url.searchParams.getAll("token").length > 1) {
    context.addIssue({ code: "custom", message: "DSH Viewer URL may contain only one launch token" });
  }
});
export type BridgeDshViewerUrl = z.infer<typeof bridgeDshViewerUrlSchema>;

export const bridgeLifecycleStateSchema = z.enum([
  "STARTING",
  "READY",
  "DEGRADED",
  "DRAINING",
  "DRAINED",
  "OFFLINE",
]);
export type BridgeLifecycleState = z.infer<typeof bridgeLifecycleStateSchema>;

export const bridgeClientRoleSchema = z.enum(["controller", "surface"]);
export type BridgeClientRole = z.infer<typeof bridgeClientRoleSchema>;

export const bridgeIdentitySchema = z.object({
  lifecycleProtocolVersion: z.literal(BRIDGE_LIFECYCLE_PROTOCOL_VERSION),
  instanceId: z.string().min(1).max(256),
  bootId: z.string().uuid(),
  bridgeVersion: z.string().min(1).max(64),
  startedAt: z.number().int().nonnegative(),
});
export type BridgeIdentity = z.infer<typeof bridgeIdentitySchema>;

export const bridgeLeaseSchema = z.object({
  ...bindingControlFields,
  leaseId: z.string().uuid(),
  clientId: z.string().min(1).max(128),
  role: bridgeClientRoleSchema,
  bootId: z.string().uuid(),
  acquiredAt: z.number().int().nonnegative(),
  expiresAt: z.number().int().positive(),
  browserOrigins: bridgeBrowserOriginsSchema,
  dshViewerUrl: bridgeDshViewerUrlSchema.optional(),
});
export type BridgeLease = z.infer<typeof bridgeLeaseSchema>;

export const bridgeStatusSchema = z.object({
  ...bridgeIdentitySchema.shape,
  state: bridgeLifecycleStateSchema.exclude(["OFFLINE"]),
  stateChangedAt: z.number().int().nonnegative(),
  activeLeaseCount: z.number().int().nonnegative(),
  inFlightRequestCount: z.number().int().nonnegative(),
  degradedReason: z.string().min(1).max(512).optional(),
  drainRequestId: z.string().uuid().optional(),
});
export type BridgeStatus = z.infer<typeof bridgeStatusSchema>;

export const bridgeOfflineStatusSchema = z.object({
  lifecycleProtocolVersion: z.literal(BRIDGE_LIFECYCLE_PROTOCOL_VERSION),
  state: z.literal("OFFLINE"),
  stateChangedAt: z.number().int().nonnegative(),
  lastKnownIdentity: bridgeIdentitySchema.optional(),
  reason: z.string().min(1).max(512).optional(),
});
export type BridgeOfflineStatus = z.infer<typeof bridgeOfflineStatusSchema>;
export type ObservedBridgeStatus = BridgeStatus | BridgeOfflineStatus;

export const bridgeControlHandshakeRequestSchema = z.object({
  ...bindingControlFields,
  lifecycleProtocolVersion: z.literal(BRIDGE_LIFECYCLE_PROTOCOL_VERSION),
