import type { DeletedReferenceBinding, HostSourceAdapter, SentReferenceBinding } from "dsh-annotation-core/host-api";

import { BridgeHttpError, BridgeUnavailableError, type BridgeHttpClient } from "../bridge/http-client.ts";
import { ANNOTATION_PROTOCOL_VERSION } from "../protocol.ts";

type SourceBridge = Pick<BridgeHttpClient, "refreshReference" | "discardReference" | "commitBacklink" | "deleteCommittedReference">;
type ReferenceItem = SentReferenceBinding["item"];

type SourcePreparationErrorCode =
  | "online-refresh-failed"
  | "source-missing"
  | "source-changed"
  | "protocol-mismatch";

class ObsidianSourcePreparationError extends Error {
  constructor(readonly code: SourcePreparationErrorCode, message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "ObsidianSourcePreparationError";
  }
}

function obsidianItem(item: ReferenceItem): asserts item is Extract<ReferenceItem, { sourceType: "obsidian-note" }> {
  if (item.sourceType !== "obsidian-note") {
    throw new ObsidianSourcePreparationError("protocol-mismatch", "Obsidian adapter received a non-Obsidian reference");
  }
}

function offline(item: Extract<ReferenceItem, { sourceType: "obsidian-note" }>): ReferenceItem {
  return { ...item, snapshot: { ...item.snapshot, freshness: "offline" } };
}

function preparationError(error: unknown): ObsidianSourcePreparationError {
  if (error instanceof ObsidianSourcePreparationError) return error;
  if (error instanceof BridgeHttpError) {
    if (error.code === "source-changed") return new ObsidianSourcePreparationError("source-changed", error.message, { cause: error });
    if (error.code === "note-not-found") return new ObsidianSourcePreparationError("source-missing", error.message, { cause: error });
    if (error.code === "protocol-mismatch") return new ObsidianSourcePreparationError("protocol-mismatch", error.message, { cause: error });
  }
  return new ObsidianSourcePreparationError("online-refresh-failed", error instanceof Error ? error.message : String(error), { cause: error });
}

export function createObsidianSourceAdapter(defaultBridge: SourceBridge, forVault?: (vaultId:string)=>SourceBridge): HostSourceAdapter {
  const route=(item:ReferenceItem)=>{obsidianItem(item);return forVault?.(item.locator.vaultId)??defaultBridge;};
  return {
    async prepare(item, signal) {
      obsidianItem(item);
      let result;
      try {
        result = await route(item).refreshReference(item.referenceId, item.snapshot.documentHash, signal);
      } catch (error) {
        if (error instanceof BridgeUnavailableError) return offline(item);
        throw preparationError(error);
      }
      if (result.kind === "offline") return offline(item);
      if (result.kind === "blocked") {
        const code = result.reason === "note-missing" || result.reason === "block-missing"
          ? "source-missing"
          : "source-changed";
        throw new ObsidianSourcePreparationError(code, `Obsidian source cannot be prepared: ${result.reason}`);
      }
      if(result.source.locator.vaultId!==item.locator.vaultId)throw new ObsidianSourcePreparationError("protocol-mismatch","Refreshed reference changed its Vault identity");
      return { ...item, ...result.source };
    },
    async discardPending(item) {
      obsidianItem(item);
      await route(item).discardReference(item.referenceId);
    },
    async commitBacklink(binding: SentReferenceBinding) {
      obsidianItem(binding.item);
      return route(binding.item).commitBacklink({
        annotationProtocolVersion: ANNOTATION_PROTOCOL_VERSION,
        type: "backlink-commit",
        referenceId: binding.referenceId,
        setId: binding.setId,
        profileId: binding.profileId,
        sessionId: binding.sessionId,
        userMessageId: binding.userMessageId,
        userAnchorId: binding.userAnchorId,
        userTextHash: binding.userTextHash,
      });
    },
    async deleteCommitted(binding: DeletedReferenceBinding) {
      obsidianItem(binding.item);
      await route(binding.item).deleteCommittedReference({
        annotationProtocolVersion: ANNOTATION_PROTOCOL_VERSION,
        type: "reference-delete-commit",
        referenceId: binding.referenceId,
        profileId: binding.profileId,
        sessionId: binding.sessionId,
        setId: binding.setId,
        deletedAt: binding.deletedAt,
      });
    },
  };
}

import {assertSessionAvailable, type SessionAvailabilityStatus} from "../session-availability.ts";
import { maintenanceLocationRequest, resolvedReferenceLocation } from "./bridge/maintenance-location.ts";
import type { Context as CordisContext } from "@deepseek-ai/cordis";
import type { AnnotationCoreHost } from "dsh-annotation-core/host-api";
import type { ObsidianBridgeLifecycle } from "../api.ts";

import { createObsidianSourceAdapter } from "./host/obsidian-source-adapter.ts";
import { createReferenceDeleteActionHandler } from "./bridge/reference-delete-actions.ts";

type Context = CordisContext & {
  annotationCoreHost: AnnotationCoreHost;
  obsidianBridgeLifecycle: ObsidianBridgeLifecycle;
};



export interface Config { profileId: string; }
export function apply(ctx: Context, config: Config): void {
  const instance = ctx.obsidianBridgeLifecycle.runtimeIdentity?.dshInstanceId;
  const instanceScope = instance === undefined ? {} : { dshInstanceId: instance };
  const bridge = ctx.obsidianBridgeLifecycle.transport!;
  const unregisterSource = ctx.annotationCoreHost.registerSourceAdapter(
    "obsidian-note",
    createObsidianSourceAdapter(bridge, ctx.obsidianBridgeLifecycle.forVault?.bind(ctx.obsidianBridgeLifecycle)),
  );
  const deleteReferenceLink = ctx.annotationCoreHost.deleteReferenceLink?.bind(ctx.annotationCoreHost);
  const unregisterAttachment = deleteReferenceLink === undefined ? () => undefined : ctx.obsidianBridgeLifecycle.registerActionHandler!(
    "references:host-deletions", {
      accepts: action => action.type === "reference-delete-request" && action.profileId === config.profileId,
      handle: async (action, _signal, route) => {
        const applyDelete = createReferenceDeleteActionHandler({ deleteReferenceLink }, route?.transport??bridge, config.profileId, {
          ...instanceScope,
          resolveSession: async action => {
            if (action.type !== "reference-delete-request") return undefined;
            const workspace=ctx.get("maintenanceInstanceWorkspace") as {sessionAvailability(logicalSessionId:string):Promise<{status:SessionAvailabilityStatus}>}|undefined;
            if(action.logicalSessionId&&workspace)assertSessionAvailable(await workspace.sessionAvailability(action.logicalSessionId));
            const resolver = ctx.get("maintenanceReferenceResolver" as never) as { resolve(input: unknown): Promise<unknown> } | undefined;
            if (resolver === undefined) return action.logicalSessionId ? undefined : action.sessionId;
            const resolved = resolvedReferenceLocation(await resolver.resolve(maintenanceLocationRequest(action)));
            return resolved?.sessionId ?? (action.logicalSessionId ? undefined : action.sessionId);
          },
        });
        return await applyDelete(action) ? "handled" : "retry";
      },
    },
  );
  ctx.effect(() => async () => {
    unregisterAttachment();
    unregisterSource();
  }, "dsh-obsidian-bridge: references: host");
}

